"use client"

import { Button } from "@/components/ui/button"
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard"
import { CheckIcon, CopyIcon } from "lucide-react"
import React from "react"

type CopyButtonProps = React.ComponentProps<typeof Button> & {
  value: string
  copiedTooltip?: string
  copyTooltip?: string
  showLabel?: boolean
}

export default function CopyButton({
  value,
  copiedTooltip = "Copied!",
  copyTooltip = "Copy",
  showLabel = true,
  ...props
}: CopyButtonProps) {
  const { copied, copy } = useCopyToClipboard()

  const handleCopy = async (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
    e.stopPropagation()
    await copy(value)
    if (props.onClick) props.onClick(e)
  }

  return (
    <Button
      type="button"
      aria-label={copied ? copiedTooltip : copyTooltip}
      title={copied ? copiedTooltip : copyTooltip}
      onClick={handleCopy}
      tooltip={copied ? copiedTooltip : copyTooltip}
      {...props}
    >
      {copied ? <CheckIcon /> : <CopyIcon />}
      {showLabel ? (copied ? copiedTooltip : copyTooltip) : null}
    </Button>
  )
}

"use client"

import { useCallback, useRef, useState } from "react"

type Options = {
  resetDelay?: number
}

export function useCopyToClipboard({ resetDelay = 1500 }: Options = {}) {
  const [copied, setCopied] = useState(false)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const copy = useCallback(
    async (value: string) => {
      if (!navigator?.clipboard) {
        setCopied(false)
        return
      }
      try {
        await navigator.clipboard.writeText(value)
        setCopied(true)

        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current)
        }
        timeoutRef.current = setTimeout(() => {
          setCopied(false)
          timeoutRef.current = null
        }, resetDelay)
      } catch {
        setCopied(false)
      }
    },
    [resetDelay]
  )

  // Optional: Clean up timeout if component unmounts
  // But not strictly necessary for use in most hooks

  return { copied, copy }
}
